// Unit u5: Constitutional Law II, individual rights (NCBE outline IV: state action, due process, equal protection,
// takings and other protections, the First Amendment). About half of the 25 scored Con Law questions are category IV.
// Method on every card: state action? -> which right? -> which tier? -> apply.
//
// SHAPE: 22 lessons of about 2 sittings each (state action 2, due process 4, equal protection 3, takings 2, other protections 1,
//   speech 8, religion 2). The NCBE outline gives no per-topic weights, so the mix is our choice, not a fact: speech and religion
//   (outline IV.F) get the most lessons because the outline lists the most sub-topics there; takings and state action are smaller.
//
//   The brief asked for 8 lessons and about 60 items; this unit has 22 lessons and about 230 items. Nobody has confirmed that the
//   larger shape is wanted: a reviewer should decide whether to cut it.
// UNDER REVIEW (status "unsure", never drawn by the Question of the Day or the mocks):
//   - u5-r-displays: Stone v. Graham has not been overruled, but the en banc Fifth Circuit (Nathan v. Alamo Heights ISD, Apr. 21, 2026,
//     9-8, via secondary reports) held it no longer controls after Kennedy and upheld Texas S.B. 10; the Louisiana case (Roake v. Brumley)
//     was vacated below. Check Supreme Court dockets No. 26-257 (Nathan) and No. 25-1360 (Brumley v. Roake) before release.
//   u5-c-devillier was verified against the opinion text (Devillier v. Texas, No. 22-913, Apr. 16, 2024, Thomas, J., 9-0) and is "book".
// RECENT (recent: true, probably not on a 2027 MBE, never the only route to a skill): Wolford, Hemani, Callais, B.P.J., Barbara,
//   Skrmetti, Free Speech Coalition v. Paxton, Chiles, NRSC, Ellingburg, Catholic Charities, Mahmoud, Drummond, Landor. They appear on
//   case cards and as one-line exceptions (Mahmoud, Paxton), never as the only route to a skill. Wolford, Hemani, Callais and Barbara were
//   checked against the Court's syllabi and B.P.J. against the LII opinion text; the rest rest on secondary reports [S] or memory and
//   stay "general": a reviewer should re-read each syllabus before release. NRSC is dated June 30, 2026 from secondary reports.
//   Little v. Hecox (No. 24-38), the B.P.J. companion, raised a mootness request; its disposition is not confirmed here.
// MBE ONLY (exam: ["mbe"], so a NextGen candidate can switch them off; conlaw.md §2): Contracts Clause, bills of attainder, privileges and
//   immunities. Right to vote, right to travel and right to bear arms are the NextGen-named SDP topics; they are inherited by both exams.
//   NCBE's "recall-only" markers in the NextGen outline did not survive PDF text extraction, so none are flagged here.
// CHECK BEFORE RELEASE:
//   - u5-r-displays: see UNDER REVIEW. McCreary (Lemon purpose) and County of Allegheny (endorsement) are taught as results only.
//   - u5-c-lawrence and u5-c-plyler deliberately state no tier of scrutiny (the opinions did not). Cruzan only assumed a protected interest
//     in refusing treatment and Moore v. East Cleveland is a plurality: neither is stated as a settled tier.
//   - u5-r-bruen: Rahimi (2024) refined Bruen; Wolford and Hemani (2026) apply it.
//   - The right-to-travel transfer hypo (u5-h-travel-housing) and trap (u5-tr-travel-welfare) were rewritten so that neither tracks the
//     school-residence item in NCBE's free sample.
// Texas threads (hooks only; the MBE tests the federal rule, never Texas law): Lawrence, Sweatt, Rodriguez, Plyler,
//   Johnson, Walker, Santa Fe, Van Orden, Smith v. Allwright.
// TRANSFER hypos (asked cold as "new facts, same rule") use facts that no card in the lesson shows: Terry v. Adams (pre-primary),
//   Cabell (probation officers), the housing wait, Clark v. CCNV (park sleeping), an off-campus threat, a helmet law. Hypos that restate
//   a card's own example are ordinary hypos, not transfer.
